function Modal({title,children,onClose,wide=false}){const ref=useRef();useEffect(()=>{const prev=document.activeElement;ref.current.showModal();return()=>prev?.focus()},[]);return <dialog ref={ref} className={wide?'wide':''} onCancel={onClose} onClick={e=>{if(e.target===ref.current)onClose()}}><div className="modal-head"><h2>{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X size={20}/></button></div>{children}</dialog>}
