function CloudBadge({state,onRetry}){if(!state.mode)return null;const [label,tone]=CLOUD_TEXT[state.mode]||CLOUD_TEXT.local;
 const tip=state.mode==='synced'?`Inventory and purchases are shared through Supabase. Last synced ${new Date(state.at||Date.now()).toLocaleTimeString()}.`:state.mode==='syncing'?'Sending changes to the shared stock.':state.mode==='local'?'The shared inventory is off: set SUPABASE_URL and SUPABASE_SECRET_KEY on the server. Inventory stays in this browser.':`${state.message||'The shared stock could not be reached.'} Changes stay on this device and are sent again. Click to try now.`;
 return <button type="button" className={'cloud-badge '+tone} title={tip} aria-label={label+'. '+tip} onClick={onRetry} disabled={state.mode==='syncing'}>{state.mode==='local'?<HardDrive size={14}/>:state.mode==='synced'||state.mode==='syncing'?<Cloud size={14}/>:<CloudOff size={14}/>}<span>{label}</span></button>}
