 const selectedKnow=useMemo(()=>selected&&knowledge?lookupPart(knowledge,{mpn:selected.mpn,value:selected.value,package:selected.package,type:selected.type}):null,[selected,knowledge]);
 const openAlternate=p=>{setSelected(p);setReference('')};const openMarket=mpn=>{if(!mpn)return;setCompareMpn(mpn);setSelected(null);setModal('compare')};const sourceAlternate=m=>openMarket(m);
 const openBoardPart=bp=>{setSelectedRef(bp.ref);setReference(bp.ref);if(bp.inv)setSelected(bp.inv);else setSelected({blueprint:true,id:'bp-'+bp.ref,ref:bp.ref,mpn:bp.mpn||bp.value||'Unnamed part',category:TYPE_CATEGORY[bp.type]||'Uncategorized',description:`${TYPE_LABELS[bp.type]||'Component'} on ${board.name}`,package:bp.package||'Unspecified',side:bp.side,x:bp.x,y:bp.y,rot:bp.rot,w:bp.w,d:bp.d,h:bp.h,type:bp.type,value:bp.value})};
 // New part numbers join the part master by themselves (saved with the other part details in this browser).
 const learn=(items,source)=>{try{const known=mpn=>{if(!knowledge)return false;const r=lookupPart(knowledge,{mpn});return !!r&&(r.match==='exact'||r.match==='variant')};
  const {next,added}=learnParts(loadDetails(localStorage),items,{source,known});if(added.length)saveDetails(localStorage,next);return added}catch{return []}};
 const boardItems=b=>(b.parts||[]).filter(p=>p.mpn&&!p.suggested).map(p=>({mpn:p.mpn,manufacturer:p.manufacturer,value:p.value,package:p.package,supplierPn:p.supplierPn,supplier:p.supplier,from:`${b.name} ${p.ref}`}));
