 const removeBoard=()=>{if(board.id==='reference')return;const remaining=boards.filter(b=>b.id!==board.id);setBoards(remaining);setBomMaps(({[board.id]:_,...rest})=>rest);setActiveBoardId(remaining.length?remaining[remaining.length-1].id:'reference');setSelectedRef(null);setHovered(null);notify(`${board.name} removed.`)};
 async function exportPlacementTemplate(){setBusy(true);try{const{default:ExcelJS}=await import('exceljs');const wb=new ExcelJS.Workbook();wb.creator='Industriverse PCBA';const ws=wb.addWorksheet('Placement');ws.columns=[{header:'Ref',key:'ref',width:10},{header:'Part number',key:'mpn',width:26},{header:'Package',key:'package',width:26},{header:'X (mm)',key:'x',width:12},{header:'Y (mm)',key:'y',width:12},{header:'Rotation',key:'rot',width:12},{header:'Side',key:'side',width:10}];[['U1','STM32F407VGT6','LQFP-100_14x14mm',50,33,0,'top'],['D1','SS14','SMA',18,42,0,'top'],['C1','GRM188R71C104KA01D','0603',32,10,90,'top']].forEach(r=>ws.addRow(r));ws.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};ws.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF163D36'}};ws.getRow(1).height=28;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([await wb.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));a.download='industriverse-pcba-placement-template.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Placement template exported.')}catch{notify('Export failed. Try again.')}finally{setBusy(false)}}
 const alerts=parts.filter(p=>status(p)!=='In stock');
