 const routeOf=()=>{if(!['Board studio','SMT line','BOM tool'].includes(page))return null;const lists=loadLists();let b=null,l=null;
  if(page==='BOM tool'){const open=settleOpenBom();if(!open||!((open.rows||[]).length||open.project||open.listId))return null;l=lists.find(x=>x.id===open.listId)||null;b=(open.fromBoard&&allBoards.find(x=>x.id===open.fromBoard))||allBoards.find(x=>x.name===open.from)||null;
   if(!l)l={id:null,name:open.project||open.from||'Untitled BOM'}}
  else{b=board;l=lists.find(x=>x.state?.fromBoard===board.id)||lists.find(x=>!x.state?.fromBoard&&x.state?.from===board.name)||null}
  const j=l?.id?production.jobs.find(x=>x.id===l.jobId)||null:null;
  return {records:{engineering:b&&{name:b.name+(b.revision?' rev '+b.revision:''),id:b.id},supply:l&&{name:l.name+(l.revision?' rev '+revLetter(l.revision):''),id:l.id},production:j&&{name:`${j.customer}, ${j.board} × ${j.qty}`,id:j.id}},
   open:k=>{if(k==='engineering'&&b){setActiveBoardId(b.id);navigate('Board studio',{handoff:true})}else if(k==='supply'&&l?.id){if(openListSafe(l.id))navigate('BOM tool',{handoff:true})}else if(k==='production')navigate('Production',{handoff:true})}}};
 const route=routeOf();
