 const boardPicker=<><select aria-label="Board" value={board.id} onChange={e=>{setActiveBoardId(e.target.value);setSelectedRef(null);setHovered(null);setListQuery('')}}><option value="reference">CTRL-01 · reference</option>{boards.map(b=><option key={b.id} value={b.id}>{b.name}{b.revision?' · '+b.revision:''}</option>)}</select>{board.id!=='reference'&&<button className="icon-button" aria-label={`Remove ${board.name}`} title="Remove this board" onClick={removeBoard}><Trash2 size={16}/></button>}</>;
 const stockValue=parts.reduce((a,p)=>a+(+p.price||0)*(+p.stock||0),0),stockUnits=parts.reduce((a,p)=>a+(+p.stock||0),0);
