 <aside className="sidebar"><a href="#/" className={'brand'+(line?'':' selected')} aria-label={`${SITE} home`} aria-current={line?undefined:'page'} onClick={e=>{e.preventDefault();navigate(HOME)}}><RouteMark/><span>Home</span></a>
  <nav aria-label="Lines">{LINES.map(l=><button key={l.id} type="button" className={'rail-tile'+(line===l.id?' selected':'')} data-line={l.id} aria-current={line===l.id?'true':undefined} title={l.label} onClick={()=>navigate(lastPage(l.id))}><l.icon size={24}/><span>{l.label}</span></button>)}</nav></aside>
