 {page==='Board studio'&&<><div className="studio-layout"><section className="panel board-panel"><div className="panel-heading"><div><div className="title-row"><h2>{board.name}</h2>{board.revision&&<span className="subtle-tag">{board.revision.toUpperCase()}</span>}{board.id!=='reference'&&<span className="subtle-tag">{board.source}</span>}</div><small>{board.id==='reference'?'Illustrative control board':'Imported blueprint'} · {Math.round(board.width)} × {Math.round(board.height)} mm{board.layers?` · ${board.layers} layers`:''}{board.glb?` · 3D model (${board.glb.unit})`:''} · {boardModel.length} components · {matched} in inventory</small></div><div className="board-switch">{boardPicker}<div className="segmented" role="group" aria-label="View">{['2D','3D'].map(m=><button className={mode===m?'active':''} aria-pressed={mode===m} onClick={()=>setMode(m)} key={m}>{m}</button>)}</div></div></div><Suspense fallback={<div className="board-placeholder">Loading studio…</div>}><Board board={board} parts={boardModel} mode={mode} onAddFiles={()=>setModal('blueprint')} selected={selectedRef} onSelect={openBoardPart} onHover={setHovered} onPick={bp=>{setSelectedRef(bp.ref);setReference(bp.ref)}} onFocus={bp=>{setSelectedRef(bp.ref);setReference(bp.ref)}}/></Suspense>{(()=>{const missing=boardModel.filter(p=>!p.suggested&&!p.mpn&&!p.inv&&!p.value).length;return missing>0&&board.id!=='reference'&&<div className="studio-note warn refetch-note" role="note"><FileUp size={15}/><span><strong>{missing} of {boardModel.filter(p=>!p.suggested).length} parts have no value or part number in these files.</strong> {board.glb?'The 3D model names only designators (R1, U1…) and footprints. Use Import BOM (a BOM with designators and part numbers) to name them on this board.':''}{board.glb?null:<>The Gerber layers{board.project?` of ${board.project}`:''} hold only designators (R1, U1…), the pads and the net on each pin. The values and part numbers are in the KiCad project they were plotted from. Add one of these to the ZIP, or import it together with the Gerbers: the board file <code>.kicad_pcb</code>, the placement file (in KiCad: File, Fabrication Outputs, Footprint Position; <code>.pos</code>), a BOM (<code>.csv</code> or <code>.xlsx</code>) or <code>ibom.html</code>.</>}</span>{board.glb?<button className="button small primary" onClick={()=>setModal('bom')} disabled={busy}><FileUp size={14}/>Import BOM</button>:<button className="button small primary" onClick={()=>setModal('blueprint')} disabled={busy}><FileUp size={14}/>Import with the project files</button>}</div>})()}<div className="studio-note"><Layers size={15}/> {board.id==='reference'?'Move the cursor over any component to identify it, click for details. This is a reference layout, not an imported CAD design; its copper tracks and vias are illustrative.':board.glb?`Shown from the 3D model ${board.fileName} exactly as exported (read in ${board.glb.unit}). ${boardModel.length?`${boardModel.length} components are named in it: move over one to identify it, click for details.`:'It names no components, so there is nothing to click: import the Gerber or KiCad files for the parts.'} The model is kept in this browser.`:board.surface?`Built from the Gerber set ${board.fileName}: ${String(board.notes||'').replace(/\.$/,'')}. The outline, copper, solder mask, silkscreen and holes are exact; component bodies are sized from their pads.`:board.image?`Built from ${board.fileName} by ${board.detector==='claude'?'Claude vision':'the local picture detector'}. ${board.notes||''} Positions and sizes follow the drawing; add parts to inventory to track them.`:`Built from ${board.fileName}. Body sizes come from package names; copper, pads and the outline appear when the file includes them.${(board.traces?.top?.length||board.traces?.bottom?.length)?'':' The copper tracks and vias shown are illustrative, because this file has no routing.'}`}</div></section><section className="panel board-list"><div className="inspector" aria-live="polite">{focusPart?<><PartSummary part={focusPart}/><div className="inspector-actions"><button className="button small" onClick={()=>openBoardPart(focusPart)}>Details <ArrowRight size={14}/></button>{(focusPart.inv?.mpn||(focusPart.mpn&&focusPart.mpn!=='Unnamed part'))&&<button className="button small primary" onClick={()=>{setCompareMpn(focusPart.inv?.mpn||focusPart.mpn);setModal('compare')}}><Radar size={14}/>Compare suppliers</button>}{focusPart.inv?<button className="button small" onClick={()=>openMarket(focusPart.inv.mpn)}>Market <ArrowUpRight size={14}/></button>:<button className="button small" onClick={()=>{setAddDefaults(toDefaults(focusPart));setModal('add')}}><Plus size={14}/>Add to inventory</button>}</div><PartModel3D part={focusPart} notify={notify}/><PartKnowledge know={focusPart.know} parts={parts} compact onOpenInventory={openAlternate} onSource={sourceAlternate}/></>:<div className="inspector-empty"><MousePointerClick size={20}/><strong>Identify a component</strong><small>Move the cursor over any chip, diode or passive on the board. Its name and stock appear here and beside the cursor.</small></div>}</div><div className="panel-heading"><h2>Board components</h2><span className="count-label">{boardModel.length}</span></div>{boardModel.length>12&&<div className="list-search"><Search size={14}/><input aria-label="Find a board component" value={listQuery} onChange={e=>setListQuery(e.target.value)} placeholder="Find ref, part or package…"/></div>}<div className="board-list-scroll">{boardModel.filter(p=>!listQuery||(p.ref+' '+displayName(p)+' '+p.package+' '+p.value).toLowerCase().includes(listQuery.toLowerCase())).slice(0,400).map(p=><button key={p.ref} className={'board-list-item '+(selectedRef===p.ref?'active':'')} onClick={()=>openBoardPart(p)} onPointerEnter={()=>setHovered(p)} onPointerLeave={()=>setHovered(null)}><span className="ref-chip">{p.ref}</span><span><strong>{displayName(p)}</strong><small>{p.inv?p.inv.package:!p.mpn&&!p.value?'No part number in the files':(p.package||TYPE_LABELS[p.type])}{p.side==='bottom'?' · bottom':''}</small></span><i className={'stock-dot '+(p.inv?(status(p.inv)==='In stock'?'green':status(p.inv)==='Low stock'?'amber':'red'):'')} title={p.inv?status(p.inv):'Not in inventory'}/><ChevronRight size={15}/></button>)}</div></section></div><MarketChart parts={boardModel} onFocus={(p,pin)=>{if(pin){setSelectedRef(p.ref);setReference(p.ref)}else setHovered(p)}} onCompare={mpn=>{setCompareMpn(mpn);setModal('compare')}}/><BoardKnowledge analysis={analysis} parts={boardModel} suggested={suggestedCount} onAdd={addSuggestions} onRemove={removeSuggestions} onBrowse={()=>navigate('Board types')}/>{bom&&<section className="panel bom-panel"><div className="panel-heading"><h2>Imported BOM availability</h2><span className="subtle-tag">Not a CAD import</span></div><div className="table-scroll"><table><thead><tr><th>MPN</th><th>Required</th><th>In inventory</th><th>Build coverage</th></tr></thead><tbody>{bom.map((p,i)=>{const match=parts.find(x=>x.mpn.toUpperCase()===p.mpn.toUpperCase());return <tr key={i}><td>{p.mpn}</td><td>{fmt(p.required)}</td><td>{match?fmt(match.stock):'Not found'}</td><td><Badge value={match&&match.stock>=p.required?'In stock':'Low stock'}/></td></tr>})}</tbody></table></div></section>}</>}
