 {page==='Integrations'&&<><div className="notice"><ShieldCheck size={16}/><span><strong>Keys stay on the server.</strong> They are read from the server's environment; none is stored in the browser or shown here.</span></div><section className="panel supplier-grid"><div className="panel-heading"><div><h2>Where prices come from</h2><small>Checked in this order: own stock, authorised distributors, registered vendors, open market.</small></div></div><div className="table-scroll"><table><thead><tr><th>Source</th><th>Status</th><th>Needs</th><th>Link</th></tr></thead><tbody>{SOURCES.map(([n,key,blurb,secrets,hint,url])=><tr key={n}><td><strong>{n}</strong><small className="price-note">{blurb}</small></td><td>{api?.[key]?<span className="badge green"><span/>Configured, not verified</span>:<span className="badge neutral"><span/>Not set up</span>}</td><td>{secrets.split('\n').map((v,i)=><React.Fragment key={v}>{i>0&&<br/>}<code>{v}</code></React.Fragment>)}<small className="price-note">{hint}</small></td><td><a className="text-button" href={url} target="_blank" rel="noreferrer">Developer portal <ExternalLink size={14}/></a></td></tr>)}</tbody></table></div></section><section className="panel setup-panel"><h2>Configuration</h2><p className="small-copy">{api?'Read from the server just now.':'The server did not answer. Prices from your own stock still work.'}</p><button type="button" className="button" onClick={async()=>{try{const r=await fetch('/api/status');if(!r.ok)throw Error();setApi(await r.json());notify('Configuration read again.')}catch{notify('The server did not answer. Try again.')}}}><RefreshCw size={16}/>Check configuration</button></section><section className="panel setup-panel"><h2>Sample data</h2><p className="small-copy">{hasSamples?'Sample components and jobs are loaded. Remove them to keep only your own records.':'Twelve sample components and four production jobs, to try the site before importing your own.'}</p>{hasSamples?<button type="button" className="button" onClick={removeSamples}><Trash2 size={16}/>Remove sample data</button>:<button type="button" className="button" onClick={loadSamples}><Database size={16}/>Load sample data</button>}</section></>}
